plist.dict:
{%- if stt %}
  NSMicrophoneUsageDescription
  Dictation turns your voice into text on this computer. Nothing is sent anywhere.
{%- elsif web_wrapper and web_microphone %}
  NSMicrophoneUsageDescription
  {{app_name}} lets the site you opened use the microphone, as you allowed in Preferences.
{%- endif %}
{%- if web_wrapper and web_camera %}
  NSCameraUsageDescription
  {{app_name}} lets the site you opened use the camera, as you allowed in Preferences.
{%- endif %}
